) AS (
  VALUES 
    (458::BIGINT, 'Es buena pero no hace fácil el curso, si una se esfuerza es probable que pase'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'ee9829d09e9cfe6e9afa7e2eac5451c2b2d650a34def3833fe16d60c7935e38f'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'No vale la pena. Que todos los semestres tenga que hacer curvas porque hay mucho quedado dice todo. NO sirve como profesora para nada, siento que ni ella sabe qué quiere de uno en las evaluaciones. La curva depende del agrado que tenga por usted. Es subjetiva heavy.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '6cec74fbe47232c878978c33b1069227c28634e7f0907bf1d251540fb6fa72aa'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Es un curso dificil, le da mucha profundidad teorica la profe. Es bueno porque ensena su manera de abordar el aprendizaje, es duro pero es sirve a largo plazo. Si se puede sentir que no se va a pasar pero al final hace de todo en la nota para que pasen todos, la gente pasa con 20 en los examenes'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '2fcf00a9b7c22003004402a1b54e9799df92daf77c549cb15c03ad56cf39090a'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Si lo van a llevar con ella van a aprender mucho, eso si, deben estudiar y hacer las cosas bien porque ella evalúa absolutamente todo y no pierde ningún detalle'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-11-09T00:00:00+00:00'::TIMESTAMPTZ, '182323a2687f06ca858f83a1ed7d9a534c210bfd2189a2d78e571812e23435c8'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Es un curso en el que usted va a aprender demasiado, la profe explica muy bien pero evalúa bastante pesado Mientras no falte a ninguna clase y estudie puede pasarlo bien, al final la profe da puntos'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-22T00:00:00+00:00'::TIMESTAMPTZ, '4551e14d79d3145b3020da67d2799e24429d1ff1cb5e320dc3af7d62c718c642'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Con esta profe sepa que si va a aprender, eso si es muy difícil y tedioso. Le recomiendo que no falte a ninguna clase, tome apuntes y preste atención. Los exámenes son difíciles y a todos les va mal, pero no se rinda, póngale y haga todos los trabajos, al final ella da muchos puntos extra y se pasa'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, '9a75f21dc6f7bc37ce74fd0ab5b5def13f8f843d2fc5049eb6f1654f85cdbd60'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'La profe es buena y la materia es sencilla, el curso es importante para el TFG, pero las evaluaciones son extensas y confusas. Para el proyecto tenga un buen grupo de trabajo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'b1b3a974de5b8487c6ed32c14f35440913fe4a171925071eeabb408df6df61bc'::TEXT, ARRAY[1797]::BIGINT[]),
    (458::BIGINT, 'La profe es re pretensiosa y crecida, ella explica bien, literal acepte que le va a ir mal en los dos examenes y haga TODO lo que tenga disponible para pasar, al final regala puntos porque al chile solo le pasan dos personas'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '9896e4bf1ff2fbc104b0ab25c7f44790c86bdeaf3c63ef56f3539e24e61f14af'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Los exámenes son difíciles (en especial el primero). No falte a ninguna clase con ella y póngale bastante en los exámenes. De fijo va a aprender un montón con ella pero va a vivir salvando el semestre. En el proyecto califica suave.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, '899ab6176afc5b07ce7b0cfccc4d5f67d8cd0b2877248938c96be38c9474bbf9'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'La profe sabe un montón, pero en ocasiones no se sabe explicar muy bien y además de que no da las soluciones de los excels que realiza. También, las evaluaciones son muy largas y da muy poco tiempo. Hay que considerar que casi nunca pone ejercicios similares en las evaluaciones a los visto en clase.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '7c22b1190a930bdadb9c15cbd03904b5f81ddb109d454628ed213bc9933a8781'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'La profe sabe mucho y presencial explica mejor que virtual, sin embargo uno en todo el semestre siente que se va a quedar por la forma tan ruda de calificar. Si quiere aprender llévelo con ella pero sabe que la va a pasar mal'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, '74df6a5b87b9d79167dbad75889965bb1d8b627c96c19d97d068160c0fca2582'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'La profe es muy buena, tiene grandes conocimientos en distintas áreas de la carrera, sin embargo es muy difícil comprender la materia en el modo que lo da. Generalmente lo deja divagando mucho luego de cada clase. Con ella pierdes fácilmente la paz en semestre dado a su metodo de evaluación.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '2569473f35e2836c94d46495b0c7d7602eb4cc84e9885dd849eadf4c1c2049bc'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Difícil, si se aprende pero se pierde la paz en todo el semestre.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '491f43215ebda8710b6509330a5ced797e54cd7f9c671b394606f688fc6a7b52'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'No la recomiendo, las evaluaciones son muy dificiles y las clases muy agotadoras'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-25T00:00:00+00:00'::TIMESTAMPTZ, 'e2008cef76e1f3eed2c8aa6d5bd34bf3af8ab19f5e3e0803056efebcdbde8fc6'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Muy difícil'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-03T00:00:00+00:00'::TIMESTAMPTZ, '52cb5589fef2f4dd68c6599c07eb0488e5e94c4375b9b2d68e8d32cd210f5f40'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'https://zoom.us/j/94927899774?pwd=TDZKNUdTOXJ5cDJHMzZCbmc5RUozZz09'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-03T00:00:00+00:00'::TIMESTAMPTZ, 'a298a6ed1b8737041ba6f180f1ebb04c3e38e6d2c1bcf6b01dd551604430cb74'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Las clases son muy largas, las evaluaciones son de una dificultad alta.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-03-10T00:00:00+00:00'::TIMESTAMPTZ, '8454cc2066519b8a5a907c1b3d88de6bffafdc1788724516fa35b07ad90c5ed1'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Una profesora prepotente, las clases son increíblemente largas y poco dinámicas, pasa leyendo las diapositivas y sobrecarga completamente cada clase, si hay una manera clara y eficiente de enseñar esta materia esta profesora claramente no la conoce y menos busca la manera de encontrarla.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2022-03-04T00:00:00+00:00'::TIMESTAMPTZ, 'a2695acd6ec170b5c09e079c50ef2b2a15135df32888bd63d2c7e14ca525beb0'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Es una pésima profesora, es muy propotente, cree que solo lo que ella dice esta correcto, no sabe lo que quiere, porque a como nos puede pedir una cosa luego dice que no que quiere otra y al final no sabe lo que pide no es nada clara con lo que quiere, y pide cosas sin tiempo de temas no vistos'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes']::TEXT[], '2022-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'd097ac816f0e80f4822e1d4aec27676d9077d253ca1c7924dd940e3ef87c7269'::TEXT, ARRAY[1797]::BIGINT[]),
    (458::BIGINT, 'No sabe dar verano, da verano como si fuera un semestre normal por la cantidad de trabajos y la duración y dificultad de los mismos. Es muy confusa, se expone un trabajo y en la presentación le parece bien pero en la calificación corrige muchas cosas incluyendo lo que ella había calificado correcto'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2022-01-08T00:00:00+00:00'::TIMESTAMPTZ, '44ee4e247aef85df126565d0991fe073ef22345751a1212e66f5df14dcee2af1'::TEXT, ARRAY[1797]::BIGINT[]),
    (458::BIGINT, 'Es de esas profes que saben mucho y quieren transmitirlo, es exigente pero se aprende bastante; espero poder volver a llevar un curso con ella.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'cfdecff24ecfb319409c40d62e043831655daa445b087aa67b7aad9e4adf816d'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Ella es una excelente profesora. Es dificil pero ella enseña lo que verdaderamente se ve en la calle. Super recomendada si quiere aprender'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'de8dc2cdc794ff0b3f4668d3fc8a508a6242c1ccc76945857db39b240726f88c'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Excelente profesora, explica muy bien y es muy buena en consulta, es estricta ya que el curso es muy importante. Super recomendada'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'f05c6d9832d78ec30bff33b0463abe5603dc62e2a5a2a9d0495818209af8b555'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Excelente, es dura pero se aprende y busca que el estudiante aprenda, no es de quedar por gusto. La mejor profesora de la Escuela. Crack. Si le pone pasa bien y sin complicación alguna'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'c3a8ec6da973a11fe259059e736b5e33906297da5aa03989ea980fa848930cf3'::TEXT, ARRAY[1797]::BIGINT[]),
    (458::BIGINT, 'Solo hace 4 quices en todo el semestre, no le gusta que los estudiantes tengan notas altas. En la clase son pura teoria y en los examenes y quices son practicos. No deja practicas y espera que uno sepa hacer todo. No la recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2016-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'ebff3ce1515c907bf5b95c072b97111fc289c7e19680e13e2e8639ee19ca0870'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Excelente'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'dcad9a5da3551b0abea3de0ace260e5f00adc4c55d25bda23e079135706a4b97'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Excelente profesora, se interesa porque el estudiante aprenda.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '54a3698c34c1e336e643cc9c5e154e4379418aaf368521b6c02c2a203db8f4b2'::TEXT, ARRAY[1757]::BIGINT[]),
    (458::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-30T00:00:00+00:00'::TIMESTAMPTZ, '805598267ce3809133d276c83565962381bacfc4171f40bbfea6c57e975e8e14'::TEXT, ARRAY[1757]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
